quests[47408] = { id = 47408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47416] = { id = 47416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow of the Triumvirate", description = "Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer.\n\nThe Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded.\n\nIf my suspicions are correct, we may be facing a greater threat than any of us dared imagine.\n\nA dark naaru.\n\nLet us return to the Vindicaar. We will plan our next steps there.", completion = "I worried for L'ura, but this is... unthinkable.\n\nHow she must have suffered...", objectives = "Return to the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47418] = { id = 47418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Pains", description = "These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope!\n\nWith my Direhorn Growth Hormone, they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable.\n\nHa ha ha this is gonna be great!", progress = "Well? Did your hatchling try the DGH yet?", completion = "Wow! That worked even better than I thought! I'm gonna make a fortune!", objectives = "Feed the Direhorn Growth Hormone to your hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47422] = { id = 47422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dire Situation", description = "Good news, we found de source of de corruption.\n\nDe bad news, it is a ritual on de apex of Zanchul.\n\nBlood magic wielding heretics are empowering some sort of dire troll up dere.\n\nHow it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year.\n\nCome, let us stop dis heresy.", progress = "What wisdom did de loa priests give you?", completion = "I will not have dat blood in my temple!", objectives = "Slay Dregada.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47423] = { id = 47423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Practices", progress = "Hello dere.", completion = "What? Dat sneering, vile raptor zealot is calling me out for not doing my share? Bah!", objectives = "Find and slay 9 Crimson Cultists in the Terrace of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47424] = { id = 47424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - First Chromie Saved" }
quests[47428] = { id = 47428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kitty?", description = "You have to find our last guest before it's time for tea!\n\nSmoochums really likes the woods, I bet we'll find him there!", completion = "Mrrow?\n\n<You find Smoochums, but Abby is nowhere to be seen.>", objectives = "Find Smoochums in Glenbrook Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47430] = { id = 47430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonkin Monitoring", description = "<Makkaw motions for you to observe the other moonkin in the area.>", completion = "<Makkaw seems very pleased about what you have learned.>", objectives = "Observe the nearby dancing, moonfiring, and napping Moonkin Hatchlings and see what you can learn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47431] = { id = 47431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Light", description = "Alleria and I long for more time with our son, but we cannot afford to wait any longer, {name}. We must strike now.\n\nThe Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra.\n\nWith the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.", completion = "We've secured a foothold. Good.\n\nNow we take the fight to them!", objectives = "Meet Turalyon in the Krokul Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47432] = { id = 47432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de great Pa'ku.", completion = "So, you have chosen de path of Pa'ku. May de winds of war be ever in your favor.\n\nFor myself, I follow Rezan, de devilsaur loa of kings. He and I have not spoken for many years, though.\n\nPerhaps I shall pay him a visit one of dese days.", objectives = "Speak with King Rastakhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47433] = { id = 47433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensively Defensive", description = "Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure.\n\nSee, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border.\n\nCome, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.", progress = "Winds be our ally.", completion = "Oh, so dat bent-tusk nose-breather is trying to win you over with a little flight and some charm, eh?", objectives = "Patrol the skies with Hexlord Raal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47434] = { id = 47434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restraining Order", description = "\"Something feels different\"? Dat was all Raal said?\n\nHis flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad.\n\nShoo dem away before dey hurt demselves or others.", completion = "Why are you scaring away my flock?", objectives = "Shoo away 20 Pterrordax Hatchlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47435] = { id = 47435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrortorial Dispute", description = "De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it.\n\nI need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes.\n\nWhen you are done, tell Raal to get his flock under control.", completion = "Did you have to kill so many?", objectives = "Slay 6 Bloodraged Pterrordaxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47437] = { id = 47437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competitive Devotion", description = "Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat.\n\nInside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me!\n\nSomeone has corrupted our own guardians.\n\nHere, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.", completion = "Dis is worse than we thought.", objectives = "Slay the 3 Corrupted Guardians of Zanchul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47438] = { id = 47438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking a Side", progress = "Have you made a choice?", completion = "Your choice is made.", objectives = "Choose a loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47439] = { id = 47439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gonk, Lord of the Pack", description = "You can find Gonk in his lair west of here, in de Garden of the Loa.\n\nYou should be able to see his totems. Run near dem to improve your speed.\n\nI will continue to purge de heretics from dis temple.\n\nMind your manners around de loa, or he may rip your throat out.", progress = "What did he say to you?", completion = "Oh, good. He did not rip your throat out. Dat is a good sign. Come, let us show de public your choice.", objectives = "Bargain with Gonk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47440] = { id = 47440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'ku, Master of Winds", description = "Come, ride Ata de Winglord with me, and he will take us to Pa'ku.\n\nOh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.", progress = "What did she say to you?", completion = "Oh, good. She did not have you dropped. Dat is a good sign. Come, let us show de public your choice.", objectives = "Bargain with Pa'ku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47441] = { id = 47441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pests", description = "Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with.\n\nYou want some coin? Help me kill some of dese snappers.\n\nOtherwise, leave me be.", completion = "A thief has come to steal from thieves?", objectives = "Slay 8 Thieving Snappers in the Zocalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47442] = { id = 47442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", progress = "You be bitin' that ratmon yet?", completion = "Haha! Well done, wealthy stranger. When ya out and about in dese lands, keep ya eyes open. Ya never know when one of de children might be pointin' ya ta a useful place.", objectives = "Survive the Trial of Jani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47444] = { id = 47444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Leather Armor" }
quests[47445] = { id = 47445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zanchuli Council", description = "You there, Speaker of de Horde.\n\nMy spies have told me of dark heresies being practiced in our sacred temple of Zanchul.\n\nDe king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers.\n\nWe need someone more... ruthlessly neutral.\n\nGo meet Wardruid Loti down at de Zocalo and she can tell you de rest.", completion = "Welcome to de steps of Zanchul, {name}. You will be treading on sacred ground soon.", objectives = "Speak with Wardruid Loti in the Zocalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47446] = { id = 47446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Leather Armor" }
quests[47456] = { id = 47456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Void" }
quests[47461] = { id = 47461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
