quests[47463] = { id = 47463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47464] = { id = 47464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47465] = { id = 47465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47466] = { id = 47466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47473] = { id = 47473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sizing Up The Opposition", description = "Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything.\n\nThere must be another way. I do not know what it is, but I trust that we will find it.\n\nBest not keep Turalyon waiting. We must move forward.", completion = "<Turalyon listens in grim silence.>", objectives = "Speak with Turalyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47485] = { id = 47485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashvane Trading Company", description = "So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea.\n\nWe need to find out how much of this powder they have and where it's going.\n\nAn old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this.\n\nYou can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney. Tell him I sent you. He owes me a favor.", completion = "Eh? What do you want?", objectives = "Speak with Cagney at Eastpoint Station. Take the ferry from Will Melborne in Tradewinds Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47486] = { id = 47486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Shipments", description = "Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus.\n\nAshvane's onto somethin' big.\n\nThey got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\"\n\nI don't know anything about what they're makin', but I know it ain't passin' through here to Boralus.\n\nIf I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels.\n\nBut I ain't that dumb, so you gotta do it.", completion = "Sounds like they're making a ton of this stuff and keeping it under wraps.\n\nThat's bad.", objectives = "Inspect 5 Marked Goods in the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47487] = { id = 47487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Labor Dispute", description = "The Ashvane Company has been workin' their people so hard they even tried to strike! \n\nThe company brought in a bunch of goons to break it up and get everyone back to work. \n\nHeard they even shot a couple guys who tried to walk off the job.\n\nWhat say you give 'em a taste of their own brutality while you're in there?", completion = "Nobody likes livin' under the thumb of company men like that - they ain't gonna be missed.", objectives = "Slay 10 Company Watchmen, Company Enforcers, or Company Fusiliers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47488] = { id = 47488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Haulers", description = "<sniff>\n\nThey said they would feed us. Said they'd keep us warm.\n\n<Olive runs the sleeve of her coat across her nose.>\n\nBut they were mean! And it was really hard work. And when we tried to rest, they yelled at us!\n\n<sniff>\n\nI got away, but my friends are still in there.", completion = "These kids are gonna have it hard enough without being under Ashvane's thumb. Thanks for getting them out.", objectives = "Free 6 Urchin Workers from the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47489] = { id = 47489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stow and Go", description = "<Flynn lifts his collar to hide his face and speaks to you under his breath.>\n\nYou see that ship? I know that ship.\n\nLet's just say her captain and I have a little history.\n\nIt's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat.\n\nWe need to find out where it's going...\n\nHow are you in tight spaces?", completion = "You alright, mate? I'm afraid your ship's gone.\n\nSomethin' tells me you weren't really a part o' that crew anyway, were ya? Har har!", objectives = "Stow away on The Maiden's Virtue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47491] = { id = 47491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. \n\nDa undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi.\n\nIf ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.", progress = "Ya got dem bloodstones for me?", completion = "Mmm, dese will do nicely.", objectives = "Collect 6 Decaying Bloodstones for Bwonsamdi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47493] = { id = 47493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lonely Spirit", description = "Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side.\n\nWell she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait.\n\nDey both belong in my realm.\n\nGo, bring da child to her ma'da.", completion = "Who be you? Have ya seen ma'da?", objectives = "Seek out Keula within the Necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47496] = { id = 47496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bunker Buster" }
quests[47497] = { id = 47497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Goldtusk Gang", description = "Greetings, traveler, and welcome to de Goldtusk Inn!\n\nUnless you're here to kill us... In which case, get out.\n\nOtherwise, sit down and enjoy de mess!\n\nI mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it!\n\n<Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.>\n\nHa, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes.\n\nCome, let me introduce you to de staff.", progress = "My friends are waiting... Don't be rude.", completion = "Don't mind half of what those trolls say. Dey don't really mean it.", objectives = "Meet the staff of the Goldtusk Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47498] = { id = 47498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhan'ka's Lost Friend", description = "When you head up to Dead Man's Pass, be sure to say hello to Zulsan.\n\nHe's my best friend, even if he doesn't want to be near me most of de time. Ha!\n\nSeriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet.\n\nOh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?", progress = "Did you find Zulsan yet?", completion = "Thank de spirits you found Zulsan. Sandfury trolls kidnapped de rest of de gang!", objectives = "Find Zulsan in Dead Man's Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47499] = { id = 47499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grinning Idols", description = "Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling.\n\nNow, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment.\n\nWell, us four, we ain't gonna be his slaves no more.\n\nA few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.", progress = "I'd hoped I'd never have to see those idols again.", completion = "Dese be cursed and evil things.", objectives = "Collect the Idol of Binding, Idol of Immortality, and Idol of Sacrifice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47501] = { id = 47501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Work for Dirty Drinks", description = "Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass!\n\nNormally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time.\n\nI'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day!\n\nDere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.", progress = "My scorpid blood drinks are famous in de Goldtusk Gang!", completion = "I'll hold onto dis blood until we can get back to de inn to make de drinks.\n\nDon't worry, I won't let you miss out on dem. I know you're excited to try my famous scorpid blood drinks!", objectives = "Collect 20 Caustic Scorpid Blood from deathsnap scorpids in Dead Man's Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47502] = { id = 47502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Cranium Caper", description = "Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang!\n\nWe gotta get dem back.\n\nMan'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess.\n\n<Rhan'ka thinks for awhile.>\n\nI got it! You rescue 'em all!", progress = "We nothin' without our gang.", completion = "Ya one of us now, {name}.", objectives = "Rescue the kidnapped members of the Goldtusk Gang in the Sandfury Hideout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47503] = { id = 47503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gozda'kun the Slaver", description = "Dat's it. De Sandfury are officially banned from de Goldtusk Inn!\n\nYou can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it!\n\nWe gotta teach those thugs what happens when you mess with de Goldtusk Gang!\n\nGozda'kun de Slaver was bossing around de rest of de Sandfury during de attack.\n\nTake him out, and leave some Sandfury behind to spread de word.", completion = "Dat'll teach de Sandfury to fear de Goldtusk Gang!", objectives = "Kill Gozda'kun the Slaver in the Sandfury Hideout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47506] = { id = 47506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[47507] = { id = 47507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khazaduum" }
quests[47508] = { id = 47508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire At Will", description = "Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here.\n\nIt looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.", progress = "Those bats are always a nuisance to deal with. This method will be more... efficient, I believe.", completion = "We may be grounded, but that does not mean they have to rule the skies!", objectives = "Enter a Lightforged Battery and slay 30 Frenzied Plaguewings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47509] = { id = 47509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrace of the Chosen", description = "This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god.\n\nLucky for us not all of Zandalar is behind this betrayal.\n\nWe need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start.\n\nGo and see if you can muster any of the Zandalari still loyal to their king.", completion = "{name}, glad to see you are not dead yet.", objectives = "Meet Kaza'jin the Wavebinder near the Terrace of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47512] = { id = 47512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmir", description = "The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar. \n\nPrincess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar.", completion = "The swamp of Nazmir represents the largest threat to my people. I am glad you chose to help me in this.", objectives = "Speak with Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47513] = { id = 47513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'dun", description = "General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nWe are not alone in our suspicions. Speak to Princess Talanji to follow up.", completion = "Jakra'zet poses a serious threat to my kingdom and your Horde. It would be good for you to investigate his activities.", objectives = "Speak with Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47514] = { id = 47514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuldazar", description = "King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet.\n\nZuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.", completion = "My father's trust is not easily earned.\n\nBelieve me.", objectives = "Speak with Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47518] = { id = 47518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raal", description = "Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa.\n\nDey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa.\n\nCan't have dat. Let's get to de top of Zanchul and rescue my worthless husband.", progress = "Dis is a problem!", completion = "Aya... did you have to bring Loti? She is never going to let me forget about dis.", objectives = "Kill Crazzak and free Hexlord Raal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47520] = { id = 47520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walls Have Ears", description = "Yazma, mistress of spies.\n\nBah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do.\n\nWe have to kill all de spiders we see, or dat traitor Yazma will know every move we make.", progress = "Are dey dead?", completion = "Well done. Dat should blind Yazma.", objectives = "Kill 8 spiders in Zanchul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47521] = { id = 47521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight in the Garden of the Loa", description = "Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. \n\nSomething bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere.\n\nCome, let's fly dere and put an end to dese heresies.", completion = "From here we can strike back at our enemies.", objectives = "Fly with Hexlord Raal to the Garden of the Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47522] = { id = 47522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter", description = "Gonk is in danger. I can hear his call.\n\nMy loa has saved my life so many times, it is about time I return de favor.\n\nCome, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.", progress = "These zealots who follow Yazma do not fight like normal priests or traitors. Dey have dark magics, and have been planning this for a long time.", completion = "They seek to kill us. They seek to break us.\n\nAll they have done is unite us in what will be the greatest hunt the Zandalari have ever known.", objectives = "Rescue Gonk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47523] = { id = 47523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance Detected: Black Temple", description = "{name}, right on time, as always.\n\nGood news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up.  \n\nThe bad news is, we know our technique works because something has changed in the Black Temple, and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.", progress = "Be extra careful the raid on the temple turns out exactly like it did before.  One extra flap of dragonfly wings, and you might end up killing Illidan for real!  Then imagine the mess we'd be in!", completion = "What's this, {name}?\n\n\n\n\n\nThese are the plans for the raid on Mardum, were we too late?\n\nWhat's strange, is the new plan seems better than the original!  It's unlikely this is the Legion's doing, Illidan surely would have detected any fel manipulation.  So if not the Legion, who is behind this?", objectives = "Relive the assault on the Black Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47525] = { id = 47525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staying Hidden", description = "Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. \n\nIf dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem.\n\nOur best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.", completion = "I can fight no more. De blood trolls, dey are making a move on Krag'wa in a big way. Dey are going to feed him to their bloody god!", objectives = "Investigate the Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47526] = { id = 47526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing the Big Guns", description = "Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel.\n\nWith the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower.\n\nThe process takes time, though, and will likely attract the Legion's attention. Be on your guard.", completion = "<The panel is now pulsing a soft golden glow. According to Romuul, activating it should teleport the cannon to the Vindicaar.>", objectives = "Locate and secure Light's Judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47527] = { id = 47527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals of Heresy" }
quests[47528] = { id = 47528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistress of Lies", description = "If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra.\n\nMy \"high\" priestess, Yazma, is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well.\n\nShadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.", completion = "Shadra was... consumed? I have heard of such heresies in Zul'Drak, but to hear of it in Zuldazar...", objectives = "Defeat Yazma and Vol'kaal in the Garden of the Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47529] = { id = 47529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supernatural Support", description = "The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here.\n\nThink carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.", objectives = "Choose which loa you wish to obtain a blessing from.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47540] = { id = 47540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemic Restoration", description = "I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers.\n\nUse the magic of the glowflies to channel my power from the totems into me.\nSoon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.", progress = "I had hoped this ritual would never be needed.", completion = "I feel like myself again, back when I had hundreds of followers pouring their faith into me. My power will fade, but the trolls shall learn to fear Krag'wa once more!", objectives = "Activate the power of the totems and restore Krag'wa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47541] = { id = 47541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Prevention", description = "If you've brought the High Exarch back to us, you are a welcome ally indeed.\n\nMore is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy.\n\nStrong words for a priest, perhaps, but every dead man'ari is one less blade at our throats.\n\nShow them that the Light protects its chosen even as it scorches the unfaithful.\n\nWhen you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.", completion = "You fought well. The Light shines brighter, thanks to your efforts.", objectives = "Slay 20 attackers in the Shattered Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47542] = { id = 47542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegemaster Voraan" }
quests[47543] = { id = 47543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day That Chromie Dies", description = "Oh, {name}! I was just thinking about you! Talk about being at the right time in the right place!\n\nI was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great.\n\nI'm going to die in the near future. Bad times.\n\nI was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with |5{race} like you by my side. Care to join me?", progress = "I'm sure I just fall into a hole or something. This wouldn't be the first time!", completion = "That didn't go so great, did it? Maybe next time.", objectives = "Speak with Chromie, then travel to the future to find out how she dies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47545] = { id = 47545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rewind", description = "Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack!\n\nLet me know when you're ready to try again.", progress = "I sure hope we don't cause a paradox!", completion = "I guess we have plenty of leads to follow up on.\n\nWow, whoever wants to kill me really thought this through!", objectives = "Speak with Chromie again, then travel to the future and gather information from the other Wyrmrest emissaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47550] = { id = 47550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Many Advantages of Being a Time Dragon", description = "Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore.\n\nWe're going to need a little more than a few seconds to stop this attack. How does four hours sound?", completion = "Fifteen minutes isn't a whole lot of time. We're going to have to move quickly.", objectives = "Speak with Chromie a third time, then travel to the future and attempt to save her again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47551] = { id = 47551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons of Fire and Pain" }
quests[47552] = { id = 47552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistress Il'thendra" }
quests[47554] = { id = 47554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Legion's Plans", description = "Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. \n\nSkara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!", progress = "Have you found the orders and the code book?", completion = "Skara and Brae gave their lives to get us this information and the codebook. Their sacrifice will not be forgotten.\n\nNow, let us decipher the orders and see what the Legion is up to.", objectives = "Search the battlefield for Legion troops and kill them to get their Enigmatic Legion Orders. Retrieve the Army of the Light Code Book to decipher the orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47557] = { id = 47557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoldering Chronoshard", description = "This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.", sourceObjective = "Bring the Smoldering Chronoshard to Wyrmrest to unlock a time portal.", completion = "Yeeeeeowch! It's hot! What could it possibly... oh, yeah, that makes sense.", sourceObjectiveStatus = "unverified-source-field" }
quests[47558] = { id = 47558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel-Touched Chronoshard", description = "This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.", sourceObjective = "Bring the Fel-Touched Chronoshard to Wyrmrest to unlock a time portal.", completion = "A chronoshard, you say? I know what to do with those.", sourceObjectiveStatus = "unverified-source-field" }
quests[47559] = { id = 47559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleaming Chronoshard", description = "This shard of crystal glitters with a metallic sheen. Based on Chromie's reaction, it may be used to connect you to another time and place.", sourceObjective = "Bring the Gleaming Chronoshard to Wyrmrest to unlock a time portal.", completion = "Hand over that chronoshard, {name}. If you don't mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[47560] = { id = 47560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen Chronoshard", description = "This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.", sourceObjective = "Bring the Frozen Chronoshard to Wyrmrest to unlock a time portal.", completion = "I hate when they get all chilly like this.", sourceObjectiveStatus = "unverified-source-field" }
quests[47561] = { id = 47561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blistermaw" }
quests[47563] = { id = 47563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Fallen" }
quests[47564] = { id = 47564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restocking the Buffet", progress = "Dis buffet is going to be a disaster if we don't get dat fruit!", completion = "Breakfast is served!", objectives = "Collect 10 Whistlebloom Juicy Fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47566] = { id = 47566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'zoth" }
quests[47570] = { id = 47570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Motives", description = "I do not understand why the naga would bother attacking a small fishing village.\n\nWhy waste their time on our simple tribe? The naga seek power and we have none. It makes no sense!\n\nThey must be after something else entirely...\n\nSearch Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful.\n\nPerhaps if we find it first, we can use it against them!", progress = "Have you uncovered their plans?", completion = "According to the invasion plans, the naga are after an ancient relic of extraordinary power known as the Ring of Tides. Apparently, it was lost hundreds of years ago in a battle not far from here...", objectives = "Locate the naga invasion plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47571] = { id = 47571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder's Wisdom", description = "The naga are searching for a powerful artifact called the Ring of Tides.\n\nAccording to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa.\n\nThe temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again!\n\nWe must let the tribe know what we've found!\n\nTake the invasion plans to Elder Kuppaka. He is the oldest, and wisest member of our tribe. He will know what to do.", progress = "Elder Kuppaka will know what to do.", completion = "The temple is not far away, but it lies in ruin... abandoned and overgrown.", objectives = "Deliver the Invasion Plans to Elder Kuppaka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47573] = { id = 47573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungleweb Infestation", description = "The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders.\n\nWe'll need to clear out the infestation before the tribe can take refuge at the temple.\n\nVenture into the lower ruins and lay waste to the spiders that have nested there.", completion = "Now that the spider infestation has been removed, we can safely relocate the rest of our tribe to the temple. Thank you, {name}.", objectives = "Slay 6 Jungleweb Crawlers and 30 Jungleweb Hatchlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47574] = { id = 47574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Webbed Up", description = "The lower ruins of the temple are covered in thick webs and spider egg sacs.\n\nSome of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back.\n\nI fear for their safety.\n\nPlease head into the lower ruins and free our brethren before it's too late.", completion = "Thank you for rescuing our trapped tribesman. We'll be more careful in dealing with the infestation in the future.", objectives = "Free 8 Tortaka Tribesman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47576] = { id = 47576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Tiger", description = "The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple.\n\nHow soon the naga have forgotten their previous defeat!\n\nThey seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila.\n\nI will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers.\n\nRemind them.", progress = "Send the naga army back to the sea!", completion = "You fought bravely against the naga army and defended my temple. From this day forward, you will be an honored guest at my temple.", objectives = "Defeat the naga invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47577] = { id = 47577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Came From The Sea", description = "You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you.\n\nNaga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon.\n\nBut taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for?\n\nTake this ancient scroll and use it summon the spirits of the naga.\n\nThey will only speak truth while under its spell.", completion = "Thanks to your efforts, Darkwood Shoal is much safer now. Still, I fear that the naga will return in force to search for this Ring of Tides.\n\nWe must find a more permanent solution to this problem...", objectives = "Question 8 Naga Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47578] = { id = 47578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of the Loa", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine and make your decision. \n\nKnow that whatever you choose, you will always be welcome within these walls.", progress = "I bestow my blessing upon my followers.", completion = "So the choice has been made.\n\nIf you ever wish to change your mind, you can commune at any loa's shrine to receive their blessing.", objectives = "Commune at Kimbul's Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47580] = { id = 47580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of Mepjila", description = "Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders.\n\nMy followers fought bravely, but I arrived too late to save them.\n\nI defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win.\n\nThis mask will give you the power to enter the spirit realm and end their nightmare.\n\nDefeat the spirit of Mepjila and the curse will be broken.", progress = "You must break the curse and free the captive souls of my followers.", completion = "At long last, my ancient followers have found peace. You have served well, {name}.", objectives = "Defeat the spirit of Mepjila.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47581] = { id = 47581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Kimbul", description = "The entrance to the temple is sealed by a magical barrier.\n\nAccording to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides.\n\nThere is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves.\n\nIf you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!", progress = "The statue is somewhere within the temple ruins.", completion = "Now that you have the Ring of Tides, you'll be able to enter the temple and make contact with the loa.", objectives = "Acquire the Ring of Tides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47583] = { id = 47583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die, Die, Diemetradon", description = "We are competing, you and I and these other savages.\n\nI find this... amusing.\n\nSouth of here you will find a number of diemetradons. I challenge you, {class}, to slay more of these creatures than I.\n\nDo you accept my wager?", completion = "<It does not seem as though Tracker Burke was prepared for what befell him. He appears to be covered in small punctures and lacerations.\n\nFortunately for you, he appears to have stashed his wager in his hat.>", objectives = "Slay 8 Venomous Diemetradons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47584] = { id = 47584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorn in the Side", description = "You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! \n\nNone know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. \n\nI am here to prove it.\n\nI wager that you could not slay more than eleven of the ankylodon beasts that wander this region.", completion = "<The fresh corpse of Erak appears to have been slain from behind by darts and is disturbingly missing some pieces. Conveniently, the prize money of his wager still adorns the body.>", objectives = "Slay 12 Ankylodons in the Preserve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47585] = { id = 47585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Predatory", description = "<There is a wound in his back, possibly from a knife.\n\nIt seems more than the wildlife is fighting back out here.>", completion = "Hmmm. Dese were left behind on purpose. Someone wanted us to find dem.", objectives = "Find 2 more hunters in the Preserves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47586] = { id = 47586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Hunter", description = "Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself.\n\nBut someone else is on his trail now. And dat hunter, he is a dangerous one.\n\nIf you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot!\n\nI believe he was last seen heading west...", completion = "Ye shouldn't have come.", objectives = "Track down Hemet Nesingwary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47587] = { id = 47587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Headhunter Jo", description = "He said he's hunting you. I'm not the prey, I'm the bait!\n\nBehind ye!", progress = "He's a sly one!", completion = "Ye have my thanks, {class}. I'll be on the look out for ye in the future.", objectives = "Slay Headhunter Jo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47588] = { id = 47588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Hunt" }
quests[47589] = { id = 47589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Fury", description = "The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long.\n\nChampion, you must pierce their lines and remove the barriers protecting the devastators.\n\nIf you can destroy the anchors that maintain the shields, I can cleanse them from afar.", progress = "Unless the anchors are destroyed, the devastators cannot be touched.", completion = "We may yet stand a chance.", objectives = "Destroy 3 Legion Devastators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47591] = { id = 47591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanna Buy a Lamp?", description = "Ey dere, wanna buy a lamp? You be not regrettin' it.", progress = "I promise ya don' regret dis.", completion = "See, I told ya it be a great idea!", objectives = "Purchase the Dubious Lamp from Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47592] = { id = 47592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shine Bright Like a Diamond", description = "Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.", progress = "I'm sure dis will all be worth it.", completion = "Ooh, ooh, lemme see!", objectives = "Purchase a Certified Organic Lamp Shining Kit from Griftah and use it to shine the Grimy Lamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47593] = { id = 47593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Coins, You Say?" }
quests[47594] = { id = 47594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Take Those, Thanks!", description = "These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.", progress = "Oh man, I can't wait to use these. I be thankin' you.", completion = "Dis be da best day. I'm going ta fleece dat Baron so hard his eyes be covered in more wool than a flock of sheep.", objectives = "Obtain 10,000 Coins of Air for Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47595] = { id = 47595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Don't Need Them, But I'll Take Them", description = "If you wanna collect more, Griftah not gonna argue with dat. Dat bein' said, I don't need dem as much anymore, so I be givin' you less for dem.", progress = "Another batch, huh? You be really enthusiastic about dese.", completion = "Be you sure ya wanna do dis? I got other wares that be much more interestin' and next week I be needin' more of these.", objectives = "Collect 10,000 Coins of Air for Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47596] = { id = 47596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Is No Plan \"B\"", description = "Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! \n\nWhat I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it!\n\nThat big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.", progress = "Got those parts yet?", completion = "Looks like you've got everything, well... we've got the important stuff at least. Now we've got a big repair job to do.", objectives = "Locate all parts of the A.M.O.D.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47597] = { id = 47597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Goblin Left Behind", description = "Our mission is dead in the water unless we move fast!\n\nI've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way.\n\nWe don't have much time, let's go!", completion = "Everyone's present and accounted for. Outstanding job!", objectives = "Locate and rescue the missing members of the Gob Squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47598] = { id = 47598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering and Fencing", description = "Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. \n\nThe beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. \n\nWe'll split the proceeds 80/20. Sounds fair to me.", progress = "Got anything for me?", completion = "Nice haul! This should keep the cartel off our backs.", objectives = "Collect 20 Ancient Titan Relics from the naga at the Sundered Span", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47599] = { id = 47599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge: Served Hot", description = "Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree?\n\nThe naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!", completion = "There you go! Let's have a moment of silence for the not so dearly departed.\n\nAaaaaaand... done!", objectives = "Use Ticker's Rocket Launcher to slay 4 Vilescale Behemoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47601] = { id = 47601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Evaluation", description = "We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears.\n\nLucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice.\n\nWe'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun.\n\nEverything'll be fine... unless it isn't.", completion = "Great job! The A.M.O.D. needs a few more tweaks but it'll be nothing we can't handle.\n\nOh, and hey... good shooting!", objectives = "Use the A.M.O.D. to destroy the naga camps and defeat Grobathan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47602] = { id = 47602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready For Action", description = "It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard?\n\nIn the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.", completion = "Naga, you say?\n\nSounds like quite de crisis dere. I am glad you were able to get things back together!", objectives = "Travel to Gloom Hollow and speak with Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47603] = { id = 47603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious, Magnificent Al'Abas", description = "I see you, puny mortal! I appreciate your concern for my lamp!", progress = "The very world trembles, trembles with the weight of magic. Their pockets are full of it.", completion = "You really don't see it? I can sense the magic in their pockets!", objectives = "Speak to Al'Abas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47604] = { id = 47604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Land of Magic", description = "I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it.\n\nI propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.", completion = "Fantastic, simply fantastic. This will be a profitable partnership, my puny associate.", objectives = "Speak to Al'Abas... again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47605] = { id = 47605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coins of Air", description = "I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, {name}. \n\nHowever, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though!\n\nCarry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.", completion = "I entrust you with my lamp. May our partnership be fruitful.", objectives = "Speak to Al'Abas yet again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47606] = { id = 47606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyalty Is Its Own Reward", description = "I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.", progress = "My goodness, already!?", completion = "Yes, yes, YES! Do you see the power radiating from the lamp? I can sense objects of great power that were concealed even from my mighty eyes.", objectives = "Obtain a thousand Coins of Air.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47607] = { id = 47607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Fash-Djinn", description = "With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!", progress = "Well, well, well. You continue to amuse and amaze, mortal.", completion = "You've done it! My lamp has never shone brighter. I shall continue to grant you coins, but I shall have to find new uses for the magic you provide.", objectives = "Find rare treasures in the pockets of the denizens of the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47608] = { id = 47608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Wish You Could See It" }
quests[47609] = { id = 47609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Gladiator's Chain Armor" }
