quests[47615] = { id = 47615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Warrior Plate" }
quests[47616] = { id = 47616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regal Lord Armor" }
quests[47617] = { id = 47617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Triad Regalia" }
quests[47618] = { id = 47618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Beast Set" }
quests[47619] = { id = 47619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cycle Armor" }
quests[47620] = { id = 47620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lich Lord Plate" }
quests[47621] = { id = 47621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Loa Feast", description = "The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands.\n\nGo and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.", progress = "I hunger.", completion = "<Krag'wa consumes all of the meat in a couple of gulps.> Yes! I have been hungry for so long. As my followers died, my hunger increased.\n\nPerhaps when more come to follow, eating will once again be just an enjoyable pastime.", objectives = "Kill beasts for their meat in the Upper Frogmarsh in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47622] = { id = 47622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Magical Glow", description = "Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now.\n\nIn the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.", completion = "I should have done this long ago as my followers were being murdered, but the blood trolls were always too strong.\n\nWith you lies the last and best chance of our survival.", objectives = "Collect Beautiful Glowflies in the Upper Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47623] = { id = 47623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Witch Doctor of Krag'wa", description = "I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone.\n\nI want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual.\n\nThen we can talk of revenge.", progress = "Zentimo must be honored.", completion = "Your ritual was done well.\n\nWith your help, I will not be fed to the blood trolls' god. It is I who will do the eating!", objectives = "Obtain the Scepter of Rebirth and use it to perform the Rite of Krag'wa Ritual upon Zentimo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47624] = { id = 47624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury It" }
quests[47625] = { id = 47625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual We Share" }
quests[47627] = { id = 47627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance", description = "The Army of the Light will not have fallen in vain.\n\nOur forces will assault the main encampment while we destroy their siege weapon.\n\nThis will be but the beginning of our vengeance.", progress = "Until their weapon is no longer a threat, we are cornered here like vermin.", completion = "It seems we underestimated the Legion's cunning.", objectives = "Destroy the siege weapon at the Crown of Destruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47631] = { id = 47631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous with the Libation", description = "I be honest wit' ya, mon. I be havin' little patience for goblins and their antics.\n\nGo meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail.\n\nGood luck, {name}!", completion = "Our mission is a disaster, a complete disaster!\n\nWe were about to drop anchor when naga swarmed the ship! The battle was hard, but we had the upper hand until a sea giant came out of nowhere. It beat the ship harder than a foreman beats a lazy peon.\n\nDon't worry, {name}. We'll get this plan back on track. But first, we need to get the crew together.", objectives = "Speak with Patch at the Wayward Shoals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47638] = { id = 47638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powerful Spirits", progress = "Embrace de spirits.", completion = "You are a Goldtusk now, {name}. Welcome home.", objectives = "Participate in the Goldtusk Gang initiation ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47641] = { id = 47641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Resistance", completion = "This must be it.", objectives = "Search for signs of resistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47642] = { id = 47642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Crystal", description = "<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal's surface.>\n\n<The lich speaks:>\n\nKeep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.", sourceObjective = "Seek out the lich hidden within the Ruby Dragonshrine's tree.", completion = "I think this is the spot.", sourceObjectiveStatus = "unverified-source-field" }
quests[47643] = { id = 47643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancients' Wisdom", description = "The three ancients left three clues:\n\n\"...the great nightmare...\"\n\n\"...by the water...\"\n\n\"...within the dragon's palm...\"\n\nPerhaps Chromie's attacker lies in the place the ancients describe?", sourceObjective = "Seek out the satyr hidden in the Emerald Dragonshrine.", completion = "Based on the clues the ancients gave us, this must be the spot. It HAS to be!\n\nLet's do this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[47644] = { id = 47644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Corestone", description = "<Deep within the demonic corestone, the image of a dreadlord speaks ominously:>\n\nYes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.", sourceObjective = "Uncover the dreadlord hidden near the entrance to the Obsidian Dragonshrine's cave.", completion = "I'm not a big fan of dreadlords, but I think you and I can handle one if we stick together. You ready, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[47645] = { id = 47645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidcallers' Scroll", description = "<The scroll pieces combine to form a tattered, but readable message:>\n\nThe time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.", sourceObjective = "Seek out the creature of void hidden above the Azure Dragonshrine.", completion = "I sense something... bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[47646] = { id = 47646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rope Around" }
quests[47647] = { id = 47647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monsters of Zem'lan" }
quests[47652] = { id = 47652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light Mother", description = "We must know for sure whether the Light Mother survived, {name}.\n\nXe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade.\n\nLet's head into the Xenedar and look for her. Light willing, she will return to guide us once more.", progress = "Light Mother... you must have survived...", completion = "Light be praised! This was a dark day, and many lives were lost. \n\nBut the Army endures. The Light Mother's prophecy will be fulfilled.\n\nAll is as it was meant to be.", objectives = "Find Xe'ra within the Xenedar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47653] = { id = 47653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Return", description = "Xe'ra has been saved! We have won an important victory here.\n\nThe Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain...\n\nRomuul should be able to teleport us back to the ship now. Let me know when you are ready.", completion = "The Army endures. The Light Mother's prophecy will be fulfilled.\n\nAll is as it was meant to be.", objectives = "Speak with Turalyon to return to the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47654] = { id = 47654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: The Crest of Knowledge", description = "We have all that we need now, {name}.\n\nAlleria Windrunner awaits your arrival at the Seat of the Triumvirate.\n\nDo not go alone, my friend. You will need allies to recover the Crest of Knowledge... and endure what L'ura has become.\n\nI will prepare the Vindicaar and await your return. Light be with you in that dark place.", progress = "It is a heavy burden I have placed upon you, {name}. I have faith you will not fail.", completion = "It is done. My heart mourns the loss of L'ura, but at least you brought her peace.\n\nOnce the Crown is in place, the Vindicaar will stand against the Legion's vile assault. Antorus will fall!", objectives = "Slay L'ura and retrieve the Crest of Knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47659] = { id = 47659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Hunter", description = "Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness!\n\nStop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.", completion = "Your deeds do not go unnoticed. Zentimo spoke of you, before his passing.\n\nWhen I did not bend to the blood trolls' corruption, they attacked. Now they seek to sacrifice me to their god.\n\nI have no more followers to work through, but perhaps you will help more.", objectives = "Slay Warmother Boatema near the Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47660] = { id = 47660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Idols", description = "De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic.\n\nSalvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.", progress = "My idols?", completion = "My totems! So many taken, so many broken. I know you saved what you could. It will not be enough.\n\nToo much of their once great power has been drained.", objectives = "Collect Stolen Idols of Krag'wa from the blood troll camp in the Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47663] = { id = 47663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timely Summons from Shattrath", description = "The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City, and lend her your aid.", progress = "I foresee you will need the strength of many allies to walk this path.", completion = "Oh, is it time?", objectives = "Meet with Vormu in Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47685] = { id = 47685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatekeeper's Challenge: Cunning", description = "Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic.\n\nI doubt you can relate.\n\nThe path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning.\n\nTo preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.", progress = "Display the Mark of Cunning or leave me alone.", completion = "Oh. You were successful.\n\nSurprising.", objectives = "Collect a Fragment of Acuity, Wit, and Guile and combine them into a Mark of Cunning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47686] = { id = 47686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not-So-Humble Beginnings", description = "Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening.\n\nTo the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures.\n\nIt will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.", completion = "This place has its share of secrets. Thankfully, I know enough of them to get us started.", objectives = "Meet Archmage Y'mera at the Conservatory of the Arcane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47687] = { id = 47687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatekeeper's Challenge: Mastery", description = "Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage.\n\nYou will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now.\n\nTheir echoes will try to kill you.\n\nBest all three with all your limbs intact and I will recognize your strength.", completion = "I must admit, I am impressed.", objectives = "Defeat Grand Vizier Jarasum, Arc-Consul Velara, and High Wakener Aargon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47688] = { id = 47688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasive Species", description = "We should seek out an alternate source of energy just in case I am wrong about the conduits.\n\nLuckily enough, I think I know where we can find one.\n\nThe panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers.\n\nThis is no time to be gentle with the environment--panthara devour energy to survive.\n\nSlay them and see if you cannot reclaim some of the power they have consumed.", progress = "There is always room for a backup plan. Did you find what we seek?", completion = "I had not imagined the final product to be so... sticky.\n\n<Y'mera wipes her hands on her robes.>\n\nIt will do.", objectives = "Collect 30 Partially Digested Arcana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47689] = { id = 47689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatekeeper's Challenge: Tenacity", description = "My master Archimonde was not known for his willingness to suffer indecision.\n\nHe preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him.\n\nAt the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you.\n\n Emerge unscathed and I will be forced to consider your will strong enough to proceed.", progress = "Take all the time you need. Failure is an art, I hear.", completion = "You may be worthy of the Conservatory's secrets, if you survive that long.", objectives = "Overcome the Trial of Tenacity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47690] = { id = 47690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defiler's Legacy", description = "It seems you are not so easily deterred. Very well.\n\nYour deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success.\n\nThe greatest of your challenges lies before you.\n\nYou must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil.\n\nFew have overcome this obstacle. I hope he does not make too much of a mess of you.", progress = "Archimonde himself... what have we gotten ourselves into?", completion = "I have never felt power like this before...\n\n<Y'mera handles the shard cautiously.>\n\nWe should get this to Velen as soon as we can.", objectives = "Defeat Archimonde and retrieve the Sigil of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47691] = { id = 47691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Non-Prophet Organization", description = "I have complete faith that Velen is nearby. We would know if he had been captured.\n\nAll the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance.\n\nThat is why I am going with you.\n\nWe will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.", completion = "You came upon me in a moment of reflection.\n\n<Velen peers at you with a tired expression.>\n\nThere is no time for such sentiment. We must press on.", objectives = "Locate Velen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47695] = { id = 47695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sound the Alarm", description = "Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around?\n\nSince you're already going down there... mind culling their numbers a bit?", objectives = "Kill 8 Wailing Sirens in Fogcliff Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47696] = { id = 47696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'wa the Terrible", description = "Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating!\n\nMeet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.", progress = "Do you now see my power?", completion = "The savages flee at the sight of Krag'wa! This pleases me! \n\nBut, they will come back in larger numbers soon unless their dark god is stopped. As long as you oppose them, I will grant you my boon.\n\nWhen the day of reckoning comes, you will have my aid.", objectives = "Use the power of Krag'wa to defeat the blood troll counterattack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47697] = { id = 47697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'wa's Aid", description = "Well done, {name}!\n\nBefore we left, I heard dat Princess Talanji be headed ta Gloom Hollow. She should be dere by now.\n\nWe better be headin' back. She would want ta hear da tale of ya success!", completion = "Krag'wa will make a powerful ally in de coming battle. When de blood trolls are defeated, I have no doubt many Zandalari will come to worship him.", objectives = "Report to Princess Talanji on your success.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47704] = { id = 47704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranishu Feeding Frenzy" }
quests[47705] = { id = 47705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Legion Lines" }
quests[47706] = { id = 47706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt for King K'tal", description = "Hunters! Dis challenge be for de King of de Preserves.\n\nKing K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.", progress = "Good hunting.", completion = "Impressive. De King has been dethroned.", objectives = "Recover the Skull of K'tal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47707] = { id = 47707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melting Down" }
quests[47709] = { id = 47709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Gnomeregan Run", description = "Ready for the big race today, {name}?\n\nEvery year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay!\n\nIt reminds us that no goal is too tall, even for us!  Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!", completion = "One small step for {name}, one giant leap for gnomekind!", objectives = "Race to Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47711] = { id = 47711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head of the Viper", description = "While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader.\n\nAs long as the Naga have a commander our operations here will be threatened. Take him out.", completion = "Good job, that should take some of the heat off us.", objectives = "Kill Lord Slithin at the Sundered Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47712] = { id = 47712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Devastator" }
quests[47715] = { id = 47715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47716] = { id = 47716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching the Ruins", description = "Dese dunes are crawling with assassins. Nowhere is safe, but we must press on.\n\nDe ruins aren't far from here. \n\nLet's continue our search on foot.", completion = "Serrik is weak from poison. We're running out of time.", objectives = "Find Julwaba within Zul'Ahjin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47720] = { id = 47720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eternal Vengeance" }
quests[47724] = { id = 47724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besieged" }
quests[47725] = { id = 47725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47726] = { id = 47726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47727] = { id = 47727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47728] = { id = 47728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talestra the Vile" }
quests[47733] = { id = 47733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loa-Speaker's Betrayal", description = "Listen, stranger. I don't have a lot of time left.\n\nI was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us.\n\nLook around. Dey found us!\n\nBut I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out.\n\nIt is Kihara's fault dat we are dying now. She brought dis upon us!\n\nKill her... Make her pay!", completion = "Dat snake of a womon helped Zul find de king! It is good dat she is dead, but I would have liked to kill her myself.\n\n<Zolani spits.>\n\nBwonsamdi can keep her.", objectives = "Slay Loa-Speaker Kihara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47734] = { id = 47734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partners in Heresy", description = "Rezan struggles against his bonds, but we cannot reach him.\n\nDe mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa.\n\nI must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.", progress = "Finish dis, {name}.", completion = "Good. De way forward is clear.", objectives = "Slay Soulrender Gao'tan and Darkweaver Ji'tan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47735] = { id = 47735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Tortollan Remedies", description = "Ah, yes, the situation is urgent. We must act quickly, but not hastily.\n\nThere is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one.\n\nThe first, foam bubbling from the mouth of a crab. The older, the better.\n\nThe second, the spine of a puffer fish. Venomous!\n\nThe third, a brutosaur scale.\n\nWhy? These are the secrets of my people, {name}. Longevity is cultivated like the rarest of flowers... carefully, and with much practice.", progress = "The quality of the healing depends very much on the quality of the ingredients.", completion = "They are satisfactory. I will explain in due time what they are for.", objectives = "Collect an envenomed puffer spine, a brutosaur scale, and aged crab foam for Jol the Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47736] = { id = 47736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heads Will Roll", description = "Zul's forces try to lay claim to de loa of kings's temple.\n\nYou must teach dese traitors de meaning of their actions.\n\nSweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king.\n\nWhen you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds.\n\nIn Rastakhan's name, heads will roll!", progress = "Time for us to send dese traitors a message.", completion = "When leaving a message, it is always good to use a language dey can easily understand.", objectives = "Collect 12 Traitorous Zandalari Heads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47737] = { id = 47737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Rezan", description = "De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan...\n\nDis will not come to pass! I will defend my loa with my life.\n\nCome, {name}, we go to de Temple of Rezan. We must stop dis heresy at once!", completion = "<Rastakhan glowers at the priest's corpse before him.>\n\nZul will pay for dis. Those who follow him will suffer, mark my words.", objectives = "Meet King Rastakhan at the Temple of Rezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47738] = { id = 47738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Loa", description = "Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now.\n\nDeath.\n\nHe is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful.\n\nYou must call on Rezan, loa of kings, and ask him to claim back Rastakhan's soul.\n\nUp de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us.\n\nIf not... It was nice knowing you.", completion = "<Rastakhan smiles grimly at you.>\n\nYou look like you have seen a loa. I know de feeling. Rezan will have words for me when I see him again.", objectives = "Place an Idol of Rezan at Jamil's hut and persuade Rezan to retrieve Rastakhan's soul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47739] = { id = 47739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Vengeance", description = "I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort.\n\nWe will need to remind him of his purpose. His anger.\n\nI have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood.\n\nPerhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.", progress = "I hope we are not too late, {name}.", completion = "De scent of blood is a reliable way to wake a devilsaur. De blood of traitorous wretches, even moreso.", objectives = "Gather 12 Traitor's Blood from Zul's followers in Zeb'ahari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47740] = { id = 47740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House of the King", description = "I hear Rezan's call. I will answer, but first you must help me.\n\nOur loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa.\n\nDey are sources of strength.\n\nZul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling.\n\nStop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.", completion = "My loa is not dead yet. Now ensure he stays dat way.", objectives = "Cleanse the 3 Statues of Rezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47741] = { id = 47741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Sacrifice a Loa", description = "Rezan's power is fading. My usurpers have nearly completed their task.\n\nI have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable.\n\n<Rastakhan snarls in anger.>\n\nCome! We will end dis traitor who spits in de face of all loa!\n\nDi chuka Rezan!", completion = "<Rezan's great sides heave as he recovers from his rampage. He is covered in gore.>\n\nHeretics.", objectives = "Slay Vilnak'dor and stop the sacrifice of Rezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47742] = { id = 47742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul's Mutiny", description = "A ship such as Rastakhan's Might does not readily sail without her crew.\n\nDat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has.\n\nBoard my ship. Kill those who think to rise against their king. We will take no prisoners.\n\nDe punishment for de crime of mutiny is death!", progress = "Have you answered dem, {name}?", completion = "Your hands are bloody. Good. Mutiny has no other price.", objectives = "Slay 10 mutinous Zandalari trolls aboard the flagship Rastakhan's Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47743] = { id = 47743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Child of Light and Shadow", description = "It is time, {name}.\n\nXe'ra is returned to us. We have Light's Heart. We have her Chosen One.\n\nCome, let us restore her. Let us forge a bright new path against our foes.\n\nSpeak to me when you are ready to begin.", progress = "Xe'ra...", completion = "I did not expect this of Xe'ra. Nor could I have foreseen Illidan's reaction.\n\nWe must ensure these events do not crush the spirits of our allies.", objectives = "Speak with Turalyon to revive Xe'ra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47744] = { id = 47744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke, Meat, and Pretty Flowers", description = "Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger.\n\n<Emery pats his pocket gingerly.>\n\nListen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.", progress = "You're not in a hurry, are you?", completion = "The smoke and the meat are for me. The flowers, on the other hand, are for the kids at the orphanage down the street.", objectives = "Obtain some Salted Venison Jerky, Grimm's Special Pipe Blend, and a Marigold Bouquet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47745] = { id = 47745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yeah, Definitely for the Kids", description = "I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and...\n\n...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.", progress = "What's this?", completion = "These are from Emery, I assume?\n\n<Meliana blushes.>\n\nThat dummy. Gotta admire his persistence, though...", objectives = "Deliver the Marigold Bouquet to Orphan Matron Meliana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47746] = { id = 47746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holing Up", description = "Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street!\n\n<Meliana regains her composure.>\n\nI need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky.\n\nChildren! Everybody, get into the house!", progress = "The children are priority one.", completion = "I don't know how long we'll need to stay holed up in the orphanage, but there's no way I'm letting the kids out while our prince walks the streets like some sort of madman.", objectives = "Obtain a Refurbished Military Rifle, Basic Cloth Bandages, and Salted Venison Jerky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47747] = { id = 47747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Plague with Fire", description = "One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight.\n\nI have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.", progress = "Mad Prince or drooling zombie - nobody's going to take this bar away from me without a fight!", completion = "This'll do, {class}.\n\nTake this key. You've earned it.", objectives = "Obtain a Flinty Firestarter and some Heavy Straw Rope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47748] = { id = 47748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Holing Up Complete" }
quests[47749] = { id = 47749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Fight Plague With Fire Complete" }
quests[47750] = { id = 47750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Emery", description = "We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern.\n\nTell him it's from the kids.", progress = "Say, what've you got there?", completion = "From the kids, you say?\n\n<Emery struggles to conceal a smile as he pockets the jerky.>", objectives = "Deliver the Salted Venison Jerky to Emery Neill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
